using System.Linq;using UnityEngine;using UnityEditor;using LWS.TruckSports.Editor;
namespace LWS.TruckTerrierRacing.Editor {
public static class TerrierWreckAuthoring {
 public static void Install(TerrierMatch m){m.finishDiagnostics=m.GetComponent<TerrierFinishDiagnostics>()??m.gameObject.AddComponent<TerrierFinishDiagnostics>();var old=GameObject.Find("Pooled actual Terrier truck wreck parts");if(old!=null)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Pooled actual Terrier truck wreck parts").transform;var pool=m.GetComponent<TerrierWreckPool>()??m.gameObject.AddComponent<TerrierWreckPool>();pool.match=m;m.wrecks=pool;pool.capacity=2200;var pieces=new System.Collections.Generic.List<TerrierWreckPool.Piece>();var names=new[]{"Chassis","Cab","door rt","doors lft","Whl HD FL","Whl HD FR","Whl HD RL","Whl HD RR","Exhaust","interior","mirror lft.001","mirror rt.001"};var contact=SportsEventAuthoring.Contact("TruckTerrierRacing","Wreck fragments contact",.35f,.2f);for(int owner=0;owner<12;owner++)foreach(var source in m.racers[owner].truck.visuals.GetComponentsInChildren<MeshFilter>(true).Where(f=>names.Contains(f.name))){var g=new GameObject("Actual wreck part "+owner+" · "+source.name);g.layer=2;g.transform.SetParent(root,false);g.transform.localScale=source.transform.lossyScale;g.AddComponent<MeshFilter>().sharedMesh=source.sharedMesh;var renderer=g.AddComponent<MeshRenderer>();renderer.sharedMaterials=source.GetComponent<Renderer>().sharedMaterials;var shape=g.AddComponent<BoxCollider>();shape.center=source.sharedMesh.bounds.center;shape.size=source.sharedMesh.bounds.size;shape.sharedMaterial=contact;var body=g.AddComponent<Rigidbody>();body.mass=source.name=="Cab"?2:source.name=="Chassis"?3:.5f;body.centerOfMass=shape.center;body.maxLinearVelocity=45;body.maxAngularVelocity=16;body.maxDepenetrationVelocity=2;body.linearDamping=.1f;body.angularDamping=.3f;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.isKinematic=true;var ghost=new GameObject("Recorded wreck part "+owner+" · "+source.name);ghost.transform.SetParent(root,false);ghost.AddComponent<MeshFilter>().sharedMesh=source.sharedMesh;var ghostRenderer=ghost.AddComponent<MeshRenderer>();ghostRenderer.sharedMaterials=renderer.sharedMaterials;pieces.Add(new TerrierWreckPool.Piece{owner=owner,source=source.transform,body=body,shape=shape,renderer=renderer,ghost=ghost.transform,ghostRenderer=ghostRenderer});g.SetActive(false);ghost.SetActive(false);}pool.pieces=pieces.ToArray();if(pool.pieces.Length!=144)throw new System.Exception("All twelve Terrier trucks require twelve real wreck parts");EditorUtility.SetDirty(m);}
}
}
